"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7680],{74715:e=>{e.exports=JSON.parse('{"functions":[{"name":"Accepts","desc":"True when `config` may occupy `equip_type`.","params":[{"name":"config","desc":"","lua_type":"ItemConfig"},{"name":"equip_type","desc":"","lua_type":"EquipmentType"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":173,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"ResolveEquipType","desc":"Which slot this item should go in.\\n\\n  * `preferred` wins when the item allows it,\\n  * `first_open` then falls back to the first ALLOWED type whose slot is free,\\n  * otherwise the item\'s own declared type.\\n\\nPure -- it reads the equipment but changes nothing, so a caller can ask \\"where\\nwould this land\\" without committing to it. The old Equip inlined this logic\\nafter it had already begun mutating.","params":[{"name":"equipment","desc":"","lua_type":"Equipment"},{"name":"config","desc":"","lua_type":"ItemConfig"},{"name":"preferred","desc":"","lua_type":"EquipmentType?"},{"name":"first_open","desc":"","lua_type":"boolean?\\n"}],"returns":[{"desc":"","lua_type":"EquipmentType?\\n"}],"function_type":"method","source":{"line":190,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"Create","desc":"","params":[{"name":"owner_id","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"Equipment\\n"}],"function_type":"method","source":{"line":225,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"Get","desc":"","params":[{"name":"id","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"Equipment?\\n"}],"function_type":"method","source":{"line":254,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"GetByOwner","desc":"","params":[{"name":"owner_id","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"Equipment?\\n"}],"function_type":"method","source":{"line":261,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"ForPlayer","desc":"A player\'s loadout, created on first ask.\\n\\nThis is what replaces `client.Manager.EquipmentController`. The lookup is by\\nUserId, so nothing has to hold a session record just to find a player\'s gear.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"Equipment\\n"}],"function_type":"method","source":{"line":273,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"GetSlot","desc":"","params":[{"name":"equipment","desc":"","lua_type":"Equipment"},{"name":"equip_type","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"ItemHolder?\\n"}],"function_type":"method","source":{"line":289,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"GetEquipped","desc":"","params":[{"name":"equipment","desc":"","lua_type":"Equipment"},{"name":"equip_type","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"ItemStack?\\n"}],"function_type":"method","source":{"line":296,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"IsEquipped","desc":"","params":[{"name":"equipment","desc":"","lua_type":"Equipment"},{"name":"class_name","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":304,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"Weight","desc":"","params":[{"name":"equipment","desc":"","lua_type":"Equipment"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"method","source":{"line":320,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"FindByProperties","desc":"Equipped holders whose config matches every given property.","params":[{"name":"equipment","desc":"","lua_type":"Equipment"},{"name":"properties","desc":"","lua_type":"{ [string]: any }\\n"}],"returns":[{"desc":"","lua_type":"{ ItemHolder }\\n"}],"function_type":"method","source":{"line":333,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"Equip","desc":"Put a stack into an equip slot.\\n\\nReturns what was displaced. Nothing is dropped, deleted or deferred -- if the\\ncaller ignores `Displaced`, the stack is leaked to the garbage collector, not\\nsilently destroyed inside a task.defer the way it used to be.","params":[{"name":"equipment","desc":"","lua_type":"Equipment"},{"name":"stack","desc":"","lua_type":"ItemStack"},{"name":"preferred","desc":"","lua_type":"EquipmentType?"},{"name":"first_open","desc":"","lua_type":"boolean?\\n"}],"returns":[{"desc":"","lua_type":"EquipResult\\n"}],"function_type":"method","source":{"line":369,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"Unequip","desc":"Take whatever is in a slot back out, and hand it to the caller.\\n\\nThe old Unequip decided for itself: `task.defer` an AddItem, and Drop if that\\nfailed. Both of those are placement decisions the caller is better placed to\\nmake -- and doing them deferred meant a failure surfaced nowhere.","params":[{"name":"equipment","desc":"","lua_type":"Equipment"},{"name":"equip_type","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"ItemStack?\\n"}],"function_type":"method","source":{"line":418,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"Swap","desc":"Exchange two equip slots.\\n\\nRefuses unless BOTH occupants may live in the other\'s slot. Every check runs\\nbefore the first write, so a refusal cannot leave one side moved -- the old\\nSwap had three separate mutate-then-fire branches, one of which fired\\nOnUpdate and two of which did not.","params":[{"name":"equipment","desc":"","lua_type":"Equipment"},{"name":"from_type","desc":"","lua_type":"string"},{"name":"to_type","desc":"","lua_type":"string\\n"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":445,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"Clear","desc":"Empties every slot and returns the contents.\\n\\nHanded back rather than destroyed: tearing down a loadout is not a reason to\\ndelete a player\'s gear. The old Clear spawned an `item:Unequip` per item on a\\nseparate thread and returned the items anyway, so callers raced it.","params":[{"name":"equipment","desc":"","lua_type":"Equipment"}],"returns":[{"desc":"","lua_type":"{ ItemStack }\\n"}],"function_type":"method","source":{"line":497,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"Destroy","desc":"","params":[{"name":"equipment","desc":"","lua_type":"Equipment"}],"returns":[{"desc":"","lua_type":"{ ItemStack }\\n"}],"function_type":"method","source":{"line":515,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"Serialize","desc":"","params":[{"name":"equipment","desc":"","lua_type":"Equipment"}],"returns":[{"desc":"","lua_type":"SerializedEquipment\\n"}],"function_type":"method","source":{"line":531,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}},{"name":"Deserialize","desc":"Rebuild a loadout from a save.\\n\\nUnknown ClassNames are skipped and reported rather than failing the load, and\\nretired ones resolve through ItemService to their replacement plus skin --\\nsame rule as InventoryService.Deserialize.","params":[{"name":"owner_id","desc":"","lua_type":"string"},{"name":"data","desc":"","lua_type":"SerializedEquipment\\n"}],"returns":[{"desc":"","lua_type":"Equipment"},{"desc":"","lua_type":"{ string }"}],"function_type":"method","source":{"line":558,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}}],"properties":[],"types":[],"name":"EquipmentService","desc":"Equipment slots, built on ItemHolder.\\n\\nReplaces Inventory/EquipmentController.luau. (Which, note, does not currently\\ncompile: it opens with seven `const` declarations, and `const` is not Luau.)\\n\\nWHAT CHANGES\\n\\nAn equip slot IS an ItemHolder -- capacity 1, plus an `Accepts` predicate that\\nencodes \\"can this item go in this slot\\". So equipment, inventory slots and\\nground piles are finally the same type, and a move between them is\\nHolderService.Transfer with no special case.\\n\\nThree behaviours are deliberately different from the old controller:\\n\\n  * Equip RETURNS what it displaced rather than disposing of it. The old one\\n    unequipped, then `task.defer`red an AddItem-or-else-Drop; if the inventory\\n    was full and Drop failed, the item was simply gone, and because the work\\n    was deferred the caller could not tell. Here the displaced stack comes back\\n    and placing it is the caller\'s decision -- the same rule the rest of\\n    Inventory2 follows.\\n\\n  * Slots are created for the declared EquipmentTypes and nothing else.\\n    GetEquipmentSlot used to lazily create a slot for ANY string, so a typo\\n    produced a real, permanently empty slot that Serialize would then walk.\\n\\n  * Nothing is validated after a mutation. Swap checked compatibility, then\\n    mutated, then fired signals; here the checks all happen first, so a\\n    refused swap cannot leave one side moved.","source":{"line":35,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/EquipmentService.luau"}}')}}]);